package singbox

import (
	"fmt"
	"net/netip"
	"time"

	"github.com/ArghTeam/razdacha/internal/ippolicy"
	"github.com/ArghTeam/razdacha/internal/store"
	C "github.com/sagernet/sing-box/constant"
	"github.com/sagernet/sing-box/option"
	"github.com/sagernet/sing/common/json/badoption"
)

const TagRealityIn = "reality-in"

// GenerateWithReality adds an authenticated ingress using a live-only context.
// Existing outgoing tunnel definitions are generated by the unchanged compiler.
func GenerateWithReality(snap store.Snapshot, plain PlainLists, live *store.RealityRuntime) (option.Options, error) {
	var plan []compiledDestination
	opts, _, err := generatePolicyWithPlan(snap, plain, &plan)
	if err != nil {
		return opts, err
	}
	if !snap.Settings.RealityEnabled {
		return opts, nil
	}
	if live == nil {
		return option.Options{}, fmt.Errorf("REALITY generation requires live authentication context")
	}
	if live.Identity == nil || len(live.Users) == 0 {
		return opts, nil
	}
	if live.Identity.ID != snap.RealityIdentityID {
		return option.Options{}, fmt.Errorf("REALITY identity does not match committed admission")
	}
	listener, err := listen("0.0.0.0", uint16(snap.Settings.RealityListenPort))
	if err != nil {
		return opts, err
	}
	users := make([]option.VLESSUser, 0, len(live.Users))
	names := make([]string, 0, len(live.Users))
	byPeer := map[string]string{}
	for _, u := range live.Users {
		if u.PeerID == "" || u.Name != store.RealityUserName(u.PeerID) || u.UUID == "" {
			return option.Options{}, fmt.Errorf("invalid live REALITY user")
		}
		if _, exists := byPeer[u.PeerID]; exists {
			return option.Options{}, fmt.Errorf("duplicate REALITY user")
		}
		byPeer[u.PeerID] = u.Name
		names = append(names, u.Name)
		users = append(users, option.VLESSUser{Name: u.Name, UUID: u.UUID})
	}
	opts.Inbounds = append(opts.Inbounds, option.Inbound{Type: C.TypeVLESS, Tag: TagRealityIn, Options: &option.VLESSInboundOptions{ListenOptions: listener, Users: users, InboundTLSOptionsContainer: option.InboundTLSOptionsContainer{TLS: &option.InboundTLSOptions{Enabled: true, ServerName: snap.Settings.RealityServerName, Reality: &option.InboundRealityOptions{Enabled: true, PrivateKey: live.Identity.PrivateKey, ShortID: []string{live.Identity.ShortID}, Handshake: option.InboundRealityHandshakeOptions{ServerOptions: option.ServerOptions{Server: snap.Settings.RealityHandshakeServer, ServerPort: uint16(snap.Settings.RealityHandshakePort)}}}}}}})
	nameByCIDR := map[string]string{}
	for _, p := range snap.Peers {
		if name, ok := byPeer[p.ID]; ok {
			prefix, e := cidr(p.Address)
			if e != nil {
				return option.Options{}, e
			}
			nameByCIDR[prefix] = name
		}
	}
	selected := func(sources []string) []string {
		if len(sources) == 0 {
			return names
		}
		var out []string
		for _, ip := range sources {
			if name, ok := nameByCIDR[ip]; ok {
				out = append(out, name)
			}
		}
		return out
	}
	rejectAction := option.RuleAction{Action: C.RuleActionTypeReject}
	inbound := func() option.Rule {
		return option.Rule{Type: C.RuleTypeDefault, DefaultOptions: option.DefaultRule{RawDefaultRule: option.RawDefaultRule{Inbound: []string{TagRealityIn}}}}
	}
	unknown := option.Rule{Type: C.RuleTypeLogical, LogicalOptions: option.LogicalRule{RawLogicalRule: option.RawLogicalRule{Mode: C.LogicalTypeAnd, Rules: []option.Rule{inbound(), {Type: C.RuleTypeDefault, DefaultOptions: option.DefaultRule{RawDefaultRule: option.RawDefaultRule{AuthUser: names, Invert: true}}}}}, RuleAction: rejectAction}}
	deniedCIDRs := append(ippolicy.LocalIPv4(), live.LocalAddresses...)
	privateReject := func(auth []string) option.Rule {
		return option.Rule{Type: C.RuleTypeDefault, DefaultOptions: option.DefaultRule{RawDefaultRule: option.RawDefaultRule{Inbound: []string{TagRealityIn}, AuthUser: auth, IPCIDR: deniedCIDRs}, RuleAction: rejectAction}}
	}
	rules := []option.Rule{
		unknown,
		{Type: C.RuleTypeDefault, DefaultOptions: option.DefaultRule{RawDefaultRule: option.RawDefaultRule{Inbound: []string{TagRealityIn}, IPVersion: 6}, RuleAction: rejectAction}},
		{Type: C.RuleTypeDefault, DefaultOptions: option.DefaultRule{RawDefaultRule: option.RawDefaultRule{Inbound: []string{TagRealityIn}, Port: []uint16{853}}, RuleAction: rejectAction}},
		{Type: C.RuleTypeDefault, DefaultOptions: option.DefaultRule{RawDefaultRule: option.RawDefaultRule{Inbound: []string{TagRealityIn}, Port: []uint16{53}}, RuleAction: option.RuleAction{Action: C.RuleActionTypeHijackDNS}}},
		privateReject(names),
	}
	rejectEndpointName := func() {
		if snap.Settings.EndpointHost != "" {
			if _, e := netip.ParseAddr(snap.Settings.EndpointHost); e != nil {
				rules = append(rules, option.Rule{Type: C.RuleTypeDefault, DefaultOptions: option.DefaultRule{RawDefaultRule: option.RawDefaultRule{Inbound: []string{TagRealityIn}, Domain: []string{snap.Settings.EndpointHost}}, RuleAction: rejectAction}})
			}
		}
	}
	rejectEndpointName()
	sharedResolve := func(withDestinationRules bool) {
		rules = append(rules, option.Rule{Type: C.RuleTypeDefault, DefaultOptions: option.DefaultRule{RawDefaultRule: option.RawDefaultRule{Inbound: []string{TagRealityIn}}, RuleAction: option.RuleAction{Action: C.RuleActionTypeResolve, ResolveOptions: option.RouteActionResolve{Server: TagDNSUpstream, Strategy: option.DomainStrategy(C.DomainStrategyIPv4Only)}}}}, privateReject(names))
		if withDestinationRules {
			// Recover matching metadata only; the original numeric destination stays
			// unchanged. Domain/FakeIP and whole-client exit paths bypass this action.
			rules = append(rules, option.Rule{Type: C.RuleTypeDefault, DefaultOptions: option.DefaultRule{
				RawDefaultRule: option.RawDefaultRule{Inbound: []string{TagRealityIn}, IPVersion: 4, Network: []string{"tcp"}},
				RuleAction: option.RuleAction{Action: C.RuleActionTypeSniff, SniffOptions: option.RouteActionSniff{
					Sniffer: []string{C.ProtocolTLS, C.ProtocolHTTP}, Timeout: badoption.Duration(300 * time.Millisecond),
				}},
			}})
			rejectEndpointName()
		}
	}
	preflight, err := realityDenialPreflight(plan, selected)
	if err != nil {
		return option.Options{}, err
	}
	inserted := false
	for _, r := range opts.Route.Rules {
		if r.Type != C.RuleTypeDefault {
			rules = append(rules, r)
			continue
		}
		raw := r.DefaultOptions.RawDefaultRule
		if len(raw.RuleSet) > 0 && !inserted {
			rules = append(rules, preflight...)
			sharedResolve(true)
			inserted = true
		}
		scoped := len(raw.SourceIPCIDR) > 0 || len(raw.RuleSet) > 0
		if !scoped {
			rules = append(rules, r)
			continue
		}
		original := r
		original.DefaultOptions.Inbound = []string{TagTProxyIn}
		rules = append(rules, original)
		auth := selected(raw.SourceIPCIDR)
		if len(auth) == 0 {
			continue
		}
		alternative := r
		alternative.DefaultOptions.SourceIPCIDR = nil
		alternative.DefaultOptions.Inbound = []string{TagRealityIn}
		alternative.DefaultOptions.AuthUser = auth
		if alternative.DefaultOptions.Action == C.RuleActionTypeRoute {
			// A singleton matcher lets the pinned controller identify this flow
			// without exposing credentials or trusting its public source address.
			for _, user := range auth {
				perUser := alternative
				perUser.DefaultOptions.AuthUser = []string{user}
				rules = append(rules, perUser)
			}
		} else {
			rules = append(rules, alternative)
		}
		if alternative.DefaultOptions.Action == C.RuleActionTypeResolve {
			rules = append(rules, privateReject(auth))
		}
	}
	if !inserted {
		sharedResolve(false)
	}
	for _, user := range names {
		rules = append(rules, option.Rule{Type: C.RuleTypeDefault, DefaultOptions: option.DefaultRule{
			RawDefaultRule: option.RawDefaultRule{Inbound: []string{TagRealityIn}, AuthUser: []string{user}},
			RuleAction:     option.RuleAction{Action: C.RuleActionTypeRoute, RouteOptions: option.RouteActionOptions{Outbound: TagDirect}},
		}})
	}
	opts.Route.Rules = rules
	dnsRules := []option.DNSRule{reject(option.RawDefaultDNSRule{Inbound: []string{TagRealityIn}, QueryType: []option.DNSQueryType{option.DNSQueryType(28)}})}
	for _, r := range opts.DNS.Rules {
		if r.Type != C.RuleTypeDefault {
			dnsRules = append(dnsRules, r)
			continue
		}
		raw := r.DefaultOptions.RawDefaultDNSRule
		if len(raw.SourceIPCIDR) == 0 && len(raw.RuleSet) == 0 {
			dnsRules = append(dnsRules, r)
			continue
		}
		original := r
		original.DefaultOptions.Inbound = []string{TagDNSIn, TagTProxyIn}
		dnsRules = append(dnsRules, original)
		auth := selected(raw.SourceIPCIDR)
		if len(auth) == 0 {
			continue
		}
		alternative := r
		alternative.DefaultOptions.SourceIPCIDR = nil
		alternative.DefaultOptions.Inbound = []string{TagRealityIn}
		alternative.DefaultOptions.AuthUser = auth
		dnsRules = append(dnsRules, alternative)
	}
	opts.DNS.Rules = dnsRules
	return opts, nil
}
